cat > flatten.py <<'EOF'
import json

def flat(o, prefix, out):
    if isinstance(o, dict):
        for k, v in o.items():
            flat(v, f'{prefix}.{k}' if prefix else k, out)
    elif isinstance(o, list):
        for i, v in enumerate(o):
            flat(v, f'{prefix}.{i}' if prefix else str(i), out)
    else:
        out[prefix] = o

out = {}
flat(json.load(open('nested.json')), '', out)
json.dump(out, open('flat.json','w'), sort_keys=True)
EOF
python3 flatten.py
